WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.customer_id, s.device, s.started_at, s.country, s.is_new_session, s.session_no, CASE WHEN device RLIKE '^(mobile|tablet)$' THEN 'OTHER_ZONE' WHEN device RLIKE '^(desktop)$' THEN 'CORE' ELSE 'PRIORITY' END AS device_zone, (SELECT MIN(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS min_account_balance FROM islands s ORDER BY device_zone NULLS LAST, session_no;
